independent.solution:
def problems(config):
    found = []
    for key, kind in [("table", str), ("batch_size", int), ("password", str)]:
        if key not in config:
            found.append(f"missing {key}")
        elif not isinstance(config[key], kind):
            found.append(f"{key} must be {kind.__name__}")
    if isinstance(config.get("batch_size"), int) and config["batch_size"] <= 0:
        found.append("batch_size must be positive")
    if config.get("password") == "":
        found.append("password is empty")
    return found

configs = [
    {"table": "orders_clean", "batch_size": 500, "password": "x"},
    {"table": "orders_clean", "batch_size": "500"},
    {"table": 5, "batch_size": 0, "password": ""},
]
for c in configs:
    print(problems(c))
